def prime_num(n: int) -> bool:
    """Return True if n is a prime number, False otherwise."""
    # Handle small cases explicitly
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Check divisors up to sqrt(n), skipping multiples of 2 and 3
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True


# Example assertion
assert prime_num(13) is True
